import { describe, expect, it } from "vitest";
import { Format } from "../../bindings/d2studio/export/models";
import fixture from "./ids.fixture.json";
import { parseAction } from "./actions";

describe("parseAction", () => {
  it("understands every ID the Go menu can produce", () => {
    // ids.fixture.json is generated by `go test ./menu -update`.
    expect(fixture.length).toBeGreaterThan(30);
    const unknown = fixture.filter((id) => parseAction(id) === null);
    expect(unknown).toEqual([]);
  });

  it("parses the simple actions", () => {
    expect(parseAction("file.save")).toEqual({ type: "save" });
    expect(parseAction("edit.undo")).toEqual({ type: "undo" });
    expect(parseAction("view.sidebar")).toEqual({ type: "toggleSidebar" });
    expect(parseAction("export.remote")).toEqual({ type: "toggleRemoteImages" });
    expect(parseAction("file.recent.clear")).toEqual({ type: "clearRecent" });
  });

  it("keeps the whole path of a recent file, including colons and backslashes", () => {
    expect(parseAction("file.recent:/Users/me/a:b c.d2")).toEqual({ type: "openRecent", path: "/Users/me/a:b c.d2" });
    expect(parseAction("file.recent:C:\\Users\\me\\win.d2")).toEqual({
      type: "openRecent",
      path: "C:\\Users\\me\\win.d2",
    });
    expect(parseAction("file.recent:")).toBeNull();
  });

  it("parses autosave choices", () => {
    expect(parseAction("autosave:off")).toMatchObject({ mode: "off" });
    expect(parseAction("autosave:blur")).toMatchObject({ mode: "blur" });
    expect(parseAction("autosave:delay:10")).toEqual({ type: "autosave", mode: "delay", delaySec: 10 });
    expect(parseAction("autosave:delay:")).toBeNull();
    expect(parseAction("autosave:delay:x")).toBeNull();
    expect(parseAction("autosave:always")).toBeNull();
  });

  it("parses export formats", () => {
    expect(parseAction("export:svg")).toEqual({ type: "export", format: Format.SVG });
    expect(parseAction("export:png")).toEqual({ type: "export", format: Format.PNG });
    expect(parseAction("export:pdf")).toEqual({ type: "export", format: Format.PDF });
    expect(parseAction("export:gif")).toBeNull();
  });

  it("parses view modes", () => {
    expect(parseAction("view.mode:preview")).toEqual({ type: "viewMode", mode: "preview" });
    expect(parseAction("view.mode:zen")).toBeNull();
  });

  it("distinguishes 'Auto' from a real engine or theme, including theme 0", () => {
    expect(parseAction("layout:")).toEqual({ type: "layout", engine: "" });
    expect(parseAction("layout:elk")).toEqual({ type: "layout", engine: "elk" });
    expect(parseAction("theme:")).toEqual({ type: "theme", id: null });
    expect(parseAction("theme:0")).toEqual({ type: "theme", id: 0 });
    expect(parseAction("theme:200")).toEqual({ type: "theme", id: 200 });
    expect(parseAction("theme:dark")).toBeNull();
  });

  it("ignores IDs it does not know", () => {
    for (const id of ["", "nope", "file.explode", "file.newer", "edit.cut"]) expect(parseAction(id)).toBeNull();
  });
});
